<?php require '../../../includes/header.php';require '../../../includes/role_guard.php';requireRole(['admin']);require '../../../includes/db.php';$tribes=[];$r=$conn->query("SELECT DISTINCT tribe FROM user_tribes WHERE tribe<>'' UNION SELECT DISTINCT tribe FROM ip_records WHERE tribe<>'' ORDER BY tribe");while($x=$r->fetch_row())$tribes[]=$x[0];$s=$_SESSION['case_import_preview']??null;$errors=['invalid_file'=>'Select a valid DOCX file.','duplicate_file'=>'This exact source file already has an import batch.','ownership_required'=>'Select operational ownership.','parse_failed'=>'The case document could not be reliably parsed.','preview_expired'=>'Preview expired. Upload again.','import_failed'=>'Import failed; no case rows were committed.'];$error=$errors[$_GET['error']??'']??'';?><main class="main-no-right"><div class="page-heading"><div><h4>Controlled Case Import</h4><p>Private preview and transactional import for the reviewed LCE DOCX structure.</p></div><a class="btn btn-light border" href="../cases.php">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['completed'])):?><div class="alert alert-success">Case import batch #<?=(int)$_GET['completed']?> completed.</div><?php endif;?><?php if(!$s||!isset($_GET['preview'])):?><section class="card-box"><form method="post" action="../../../processes/case_import_preview.php" enctype="multipart/form-data"><div class="row g-3"><div class="col-md-7"><label class="form-label">LCE case document (.docx)</label><input class="form-control" type="file" name="case_document" accept=".docx" required></div><div class="col-md-5"><label class="form-label">Operational ownership</label><select class="form-select" name="owning_tribe" required><option value="">Select scope</option><?php foreach($tribes as$t):?><option><?=e($t)?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-success">Generate Case Preview</button></div></div></form></section><?php else:$p=$s['preview'];?><div class="row g-3 mb-3"><?php foreach(['Total cases'=>$p['total'],'Valid'=>$p['valid'],'Warnings'=>$p['warning'],'Invalid'=>$p['invalid'],'Duplicates'=>$p['duplicates']]as$l=>$v):?><div class="col"><div class="card-box"><small class="text-muted"><?=$l?></small><h3><?=(int)$v?></h3></div></div><?php endforeach;?></div><div class="row g-3"><div class="col-md-5"><section class="card-box"><div class="section-title">Case Types</div><?php foreach($p['types']as$n=>$c):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=e($n)?></span><strong><?=$c?></strong></div><?php endforeach;?></section></div><div class="col-md-7"><section class="card-box"><div class="section-title">Issues</div><?php foreach($p['issues']as$i):?><p class="small"><strong>Case <?=$i['case']?>:</strong> <?=e(implode('; ',$i['issues']))?></p><?php endforeach;?><?php if(!$p['issues']):?><p class="text-muted">No issues.</p><?php endif;?></section></div></div><section class="card-box mt-3 d-flex justify-content-between align-items-center"><div><strong>Explicit confirmation required</strong><p class="text-muted mb-0">No participant will be automatically linked to a registry record.</p></div><form method="post" action="../../../processes/case_import_confirm.php"><input type="hidden" name="preview_token" value="<?=e($s['token'])?>"><button class="btn btn-success">Confirm Transactional Case Import</button></form></section><?php endif;?></main><?php require '../../../includes/footer.php';?>
